<?php declare(strict_types=1); namespace App\Tests\Imperium\Runtime;
use App\Imperium\Runtime\Imperator\ImperatorPrincipalLifecycleReconstructionService; use App\Imperium\Runtime\LaCortine\DeterministicTransitionCallerAuthorityIssuanceService; use PHPUnit\Framework\TestCase;
final class ProviderBindingActivationPrincipalProvenanceBatch7Test extends TestCase { use IronGateCallerAuthorityTestTrait; private string $root;
protected function setUp():void{$this->root=sys_get_temp_dir().'/imperium-ppr-b7-'.bin2hex(random_bytes(6));mkdir($this->root,0770,true);$this->writeImperatorPrincipal();} protected function tearDown():void{if(!is_dir($this->root))return;$i=new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($this->root,\FilesystemIterator::SKIP_DOTS),\RecursiveIteratorIterator::CHILD_FIRST);foreach($i as$x)$x->isDir()?rmdir($x->getPathname()):unlink($x->getPathname());rmdir($this->root);}
public function testExpiryIsReconstructedReadOnlyAndBlocksIssuance():void{$at=new \DateTimeImmutable('2099-08-30T00:00:00+00:00');$r=(new ImperatorPrincipalLifecycleReconstructionService($this->root))->reconstruct($this->imperatorPrincipalId,$at);self::assertSame('EXPIRED',$r['effective_status']);self::assertSame('PRINCIPAL_EXPIRY',$r['status_source']);self::assertTrue($r['read_only']);self::assertFalse($r['authority_created']);$this->expectExceptionMessage('IGA104_IMPERATOR_PRINCIPAL_INVALID');(new DeterministicTransitionCallerAuthorityIssuanceService($this->root))->issueImperator($this->imperatorPrincipalId,'ISSUE_EXACT_PROVIDER_BINDING_ACTIVATION_AUTHORITY',['id'=>'target-test','digest'=>str_repeat('a',64)],$at,$at->modify('+5 minutes'));}
public function testCampaignTerminatesWithoutImpliedContinuation():void{$h=(string)file_get_contents(dirname(__DIR__,3).'/docs/handoffs/provider-binding-activation-principal-provenance-remediation-campaign-complete.md');foreach(['CAMPAIGN_COMPLETE','no Batch 8','grants no corridor-reconsideration authority','Provider Execution Assurance remains paused','Iron Gate','Lazaretto']as$b)self::assertNotFalse(stripos($h,$b),$b);}}
